window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9509f75339a6d106"]={"versions": [{"id": "FIG-9509f75339a6d106", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- bzw. Prozessdiagramm der AUTOSAR-Methodik (Methodology Library) zur Definition von Transportprotokollen (TP). Das Diagramm spezifiziert die methodische Task „Define TP“ im Kontext des Systementwurfs sowie deren funktionale Einbettung zwischen Kommunikationskonfiguration und Netzwerktopologie.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Rolle</strong>: <code>System Engineer</code> (Kardinalität 1, Assoziation «performs»).</li>\n<li><strong>Aktivität / Task</strong>: <code>Define TP</code>.</li>\n<li><strong>Eingangsartefakte («input»)</strong>:</li>\n<li><code>Topology</code> (Kardinalität 1)</li>\n<li><code>Interaction Layer</code> (Kardinalität 0..1)</li>\n<li><strong>Ausgangsartefakte («output»)</strong>:</li>\n<li><code>Network Layer</code> (Kardinalität 1)</li>\n<li><code>Diagnostics Interaction</code> (unten rechts abgeschnitten dargestellt, Kardinalität 0..1)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aktivität <code>Define TP</code> wird durch den <code>System Engineer</code> ausgeführt. Als zwingende Eingangsgröße dient das Artefakt <code>Topology</code> (1), ergänzt durch das optionale Artefakt <code>Interaction Layer</code> (0..1). Basierend auf diesen Eingangsdaten generiert bzw. definiert der Prozessschritt das verbindliche Ausgabeartefakt <code>Network Layer</code> (1) sowie optional das Ausgabeartefakt <code>Diagnostics Interaction</code> (0..1).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodische Spezifikation für den AUTOSAR-Systementwurf. Zur Parametrierung und Auslegung der Transportprotokollebene (Network Layer / TP) muss die Topologiebeschreibung vollständig vorliegen. Falls anwendungs- oder diagnosebezogene Interaktionsschichten definiert sind, fließen diese ein bzw. werden die entsprechenden TP-Zuordnungen für Diagnose und Interaktionsschicht konfiguriert.</p>"}, {"id": "FIG-428775b59c41f159", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- bzw. Prozessdiagramm der AUTOSAR-Methodik (Methodology Library) zur Definition von Transportprotokollen (TP). Das Diagramm spezifiziert die methodische Task „Define TP“ im Kontext des Systementwurfs sowie deren funktionale Einbettung zwischen Kommunikationskonfiguration und Netzwerktopologie.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Rolle</strong>: <code>System Engineer</code> (Kardinalität 1, Assoziation «performs»).</li>\n<li><strong>Aktivität / Task</strong>: <code>Define TP</code>.</li>\n<li><strong>Eingangsartefakte («input»)</strong>:</li>\n<li><code>Topology</code> (Kardinalität 1)</li>\n<li><code>Interaction Layer</code> (Kardinalität 0..1)</li>\n<li><strong>Ausgangsartefakte («output»)</strong>:</li>\n<li><code>Network Layer</code> (Kardinalität 1)</li>\n<li><code>Diagnostics Interaction</code> (unten rechts abgeschnitten dargestellt, Kardinalität 0..1)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aktivität <code>Define TP</code> wird durch den <code>System Engineer</code> ausgeführt. Als zwingende Eingangsgröße dient das Artefakt <code>Topology</code> (1), ergänzt durch das optionale Artefakt <code>Interaction Layer</code> (0..1). Basierend auf diesen Eingangsdaten generiert bzw. definiert der Prozessschritt das verbindliche Ausgabeartefakt <code>Network Layer</code> (1) sowie optional das Ausgabeartefakt <code>Diagnostics Interaction</code> (0..1).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodische Spezifikation für den AUTOSAR-Systementwurf. Zur Parametrierung und Auslegung der Transportprotokollebene (Network Layer / TP) muss die Topologiebeschreibung vollständig vorliegen. Falls anwendungs- oder diagnosebezogene Interaktionsschichten definiert sind, fließen diese ein bzw. werden die entsprechenden TP-Zuordnungen für Diagnose und Interaktionsschicht konfiguriert.</p>"}], "trans": [{"from": "FIG-9509f75339a6d106", "to": "FIG-428775b59c41f159", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
